SELECT p.gender, i.icu_stay_id, EXTRACT(QUARTER FROM i.intime) AS procedure_quarter, COUNT(DISTINCT p.hadm_id) AS patient_count, AVG(i.los) AS average_los, SUM(CASE WHEN p.dod IS NOT NULL THEN 1 ELSE 0 END) * 100.0 / NULLIF(COUNT(DISTINCT p.hadm_id), 0) AS mortality_rate FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN icustays i ON a.hadm_id = i.subject_id WHERE p.gender = 'M' AND EXTRACT(YEAR FROM age(CURRENT_DATE, p.dob)) = 81 AND a.admission_type_id = 1 AND i.intime BETWEEN CURRENT_DATE - INTERVAL '24 hours' AND CURRENT_DATE AND i.dischtime BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL '24 hours' AND p.dod IS NOT NULL GROUP BY p.gender, i.icu_stay_id, procedure_quarter ORDER BY p.gender, i.icu_stay_id, procedure_quarter NULLS LAST;